<script setup>
import { computed, ref } from 'vue';
import { Head, Link, router, usePage, useForm } from '@inertiajs/vue3';
const props=defineProps({canLogin:Boolean,canRegister:Boolean,job:Object,relatedJobs:Array,isSaved:Boolean,application:Object,resumes:Array});
const bullets=['Fit round ad tempus duis nisi sed massa. Ornare varius facilisis enim vitae vivamus curae.','Cras facilisis dignissim augue lorem amet adipiscing cursus fames mauris.','Ornare varius facilisis nisi vitae vitae dictumst. Duis facilisis dignissim augue lorem amet.','Tortor amet porta proin in. Orci imperdiet nisi dignissim pellentesque mollis vitae.'];
const fallback={title:'Corporate Solutions Executive',company:{name:'Leffler and Sons'},category:{name:'Commerce'},employment_type:'full_time',salary_min:40000,salary_max:42000,location:'New-York, USA',description:'Nunc sed a nisl purus. Nibh est faucibus porta lacus tristique. Sit congue non vitae odio sit et in. Felis eu ultrices a sed massa.',experience_level:'5 Years',education_level:'Master',created_at:'10 min ago',skills:[]};
const current=computed(()=>props.job||fallback);
const related=computed(()=>props.relatedJobs?.length?props.relatedJobs:[{slug:'#',title:'Internal Creative Coordinator',company:{name:'Green Group'},salary_min:48000,salary_max:49000,location:'New-York, USA',employment_type:'full_time',category:{name:'Commerce'},created_at:'24 min ago'}]);
const label=v=>String(v||'Full time').replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());
const money=v=>v?`$${Number(v).toLocaleString()}`:'Negotiable';
const salary=j=>j.salary_min||j.salary_max?`${money(j.salary_min)}${j.salary_max?`–${money(j.salary_max)}`:''}`:'Negotiable';
const page=usePage();
const location=j=>j.location||[j.city,j.country].filter(Boolean).join(', ')||'Remote';
const showApply=ref(false);const applicationForm=useForm({resume_id:props.resumes?.find(r=>r.is_default)?.id||'',cover_letter:''});
const apply=()=>{if(!props.job)return;if(props.job.application_type==='external'){window.open(props.job.external_url,'_blank');return;}if(!page.props.auth.user)return router.visit(route('login'));if(page.props.auth.user.role!=='candidate')return router.visit(route('dashboard'));if(!props.application)showApply.value=true;};
const submitApplication=()=>applicationForm.post(route('applications.store',props.job.id),{preserveScroll:true,onSuccess:()=>showApply.value=false});
const save=()=>{if(!page.props.auth.user)return router.visit(route('login'));if(page.props.auth.user.role==='candidate')router.post(route('jobs.save',props.job.id),{},{preserveScroll:true});};
const list=value=>value?value.split(/\n|•/).map(v=>v.trim()).filter(Boolean):[];
const responsibilities=computed(()=>list(current.value.responsibilities));const requirements=computed(()=>list(current.value.requirements));
const contact=useForm({name:page.props.auth.user?.name||'',email:page.props.auth.user?.email||'',phone:'',message:'',job_listing_id:props.job?.id});const send=()=>contact.post(route('contact.store'),{preserveScroll:true,onSuccess:()=>contact.reset('phone','message')});
const newsletter=useForm({email:''});
</script>
<template><Head title="Job Details"/><main><section class="hero"><div class="shade"/><header class="shell nav"><Link href="/" class="brand"><img src="/images/job-portal/brand-mark.svg">Job Portal</Link><nav><Link href="/">Home</Link><a>Jobs</a><a>About Us</a><a>Contact Us</a></nav><div v-if="canLogin" class="auth"><Link v-if="$page.props.auth.user" :href="route('dashboard')">Dashboard</Link><template v-else><Link :href="route('login')">Login</Link><Link v-if="canRegister" class="btn" :href="route('register')">Register</Link></template></div></header><h1>Job Details</h1></section>
<section class="shell summary"><small>{{new Date(current.published_at||current.created_at).toLocaleDateString()}}</small><button type="button" class="save" :class="{saved:isSaved}" @click="save">{{isSaved?'♥':'♡'}}</button><div class="title"><b>◩</b><div><h2>{{current.title}}</h2><p>{{current.company?.name}}</p></div></div><div class="meta"><span>▣ {{current.category?.name}}</span><span><img src="/images/job-portal/clock.svg"> {{label(current.employment_type)}}</span><span>▤ {{salary(current)}}</span><span><img src="/images/job-portal/map-pin.svg"> {{location(current)}}</span><button @click="apply" :disabled="application">{{application?`Applied · ${label(application.status)}`:'Apply Job'}}</button></div></section>
<section class="shell layout"><article class="content"><h3>Job Description</h3><p style="white-space:pre-line">{{current.description}}</p><template v-if="responsibilities.length"><h3>Key Responsibilities</h3><ul><li v-for="b in responsibilities" :key="b">{{b}}</li></ul></template><template v-if="requirements.length"><h3>Requirements</h3><ul><li v-for="b in requirements" :key="b">{{b}}</li></ul></template><h3>Professional Skills</h3><ul><li v-for="b in (current.skills?.length?current.skills.map(s=>s.name):['Relevant professional experience','Clear written and verbal communication'])" :key="b">{{b}}</li></ul><h3>Tags:</h3><div class="tags"><span v-for="t in [label(current.employment_type),label(current.workplace_type),current.category?.name,location(current)].filter(Boolean)" :key="t">{{t}}</span></div><div class="share"><b>Share Job:</b>　◉　𝕏　in</div><h2 class="related-title">Related Jobs</h2><p>Explore similar opportunities selected for you.</p><div class="related"><div v-for="(r,i) in related" :key="r.slug"><small>{{new Date(r.published_at||r.created_at).toLocaleDateString()}}</small><span>♡</span><h3>{{['🌈','◒','◍'][i%3]}}　{{r.title}}</h3><p>{{r.company?.name}}</p><footer><em>▣ {{r.category?.name}}　 ◷ {{label(r.employment_type)}}　 ▤ {{salary(r)}}　 ⌖ {{location(r)}}</em><Link class="btn" :href="`/jobs/${r.slug}`">Job Details</Link></footer></div></div></article>
<aside><button class="apply" @click="apply" :disabled="application">{{application?`Application: ${label(application.status)}`:'Apply Job'}}</button><form v-if="showApply" class="apply-form" @submit.prevent="submitApplication"><h3>Apply for this job</h3><label><select v-model="applicationForm.resume_id"><option value="">Apply without résumé</option><option v-for="resume in resumes" :value="resume.id">{{resume.name}}{{resume.is_default?' · default':''}}</option></select></label><label class="message"><textarea v-model="applicationForm.cover_letter" placeholder="Cover letter (optional)"></textarea></label><small v-if="applicationForm.errors.resume_id">{{applicationForm.errors.resume_id}}</small><button :disabled="applicationForm.processing">Submit application</button></form><div class="overview"><h3>Job Overview</h3><dl><template v-for="x in [['Job Title',current.title],['Job Type',label(current.employment_type)],['Category',current.category?.name],['Experience',current.experience_level||'Not specified'],['Degree',current.education_level||'Not specified'],['Openings',current.openings],['Applications',current.applications_count],['Deadline',current.application_deadline?new Date(current.application_deadline).toLocaleDateString():'Open until filled'],['Offered Salary',salary(current)],['Location',location(current)]]" :key="x[0]"><dt>✓ {{x[0]}}</dt><dd>{{x[1]}}</dd></template></dl><img class="map" src="/images/job-portal/map.png"></div><form @submit.prevent="send"><h3>Send Us Message</h3><label><img src="/images/job-portal/user.svg"><input v-model="contact.name" required placeholder="Full name"></label><label><img src="/images/job-portal/mail.svg"><input v-model="contact.email" type="email" required placeholder="Email Address"></label><label><img src="/images/job-portal/phone.svg"><input v-model="contact.phone" placeholder="Phone Number"></label><label class="message"><img src="/images/job-portal/message.svg"><textarea v-model="contact.message" required placeholder="Your Message"></textarea></label><button :disabled="contact.processing">Send Message</button></form></aside></section>
<footer class="site-footer"><div class="shell foot"><div><b class="brand"><img src="/images/job-portal/brand-mark.svg">Job</b><p>Quis enim pellentesque viverra tellus eget malesuada facilisis. Congue nibh vivamus aliquet nunc mauris dui nullam et.</p></div><div><h3>Company</h3><a>About Us</a><a>Our Team</a><a>Partners</a><a>For Candidates</a><a>For Employers</a></div><div><h3>Job Categories</h3><a>{{current.category?.name}}</a><a>{{label(current.employment_type)}}</a><a>{{label(current.workplace_type)}}</a></div><form @submit.prevent="newsletter.post(route('newsletter.store'),{preserveScroll:true,onSuccess:()=>newsletter.reset()})"><h3>Newsletter</h3><p>Get new opportunities delivered to your inbox.</p><input v-model="newsletter.email" type="email" required placeholder="Email Address"><button :disabled="newsletter.processing">Subscribe now</button></form></div><div class="shell copy"><span>© Copyright Job Portal 2024. Designed by Figma.guru</span><span>Privacy Policy　 Terms & Conditions</span></div></footer></main></template>
<style scoped>
:global(body){margin:0;color:#090909}*{box-sizing:border-box}main{font-family:Figtree,Inter,system-ui,sans-serif}.shell{width:min(1296px,calc(100% - 48px));margin:auto}.hero{height:322px;background:url('/images/job-portal/details-hero.png') center/cover;color:#fff;position:relative}.shade{position:absolute;inset:0;background:#000e}.nav{height:82px;position:relative;display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:10px;color:#fff;text-decoration:none;font-size:20px}.brand img{width:28px;height:28px}.nav nav{display:flex;gap:36px}.nav nav a,.auth a{color:#fffa;text-decoration:none}.auth{display:flex;align-items:center;gap:20px}.btn,button{background:#309689;color:#fff;border:0;border-radius:8px;padding:12px 20px;font-weight:650}.hero h1{position:relative;text-align:center;font-size:60px;margin:55px 0 0}.summary{padding:60px 0 50px;position:relative;border-bottom:1px solid #eee}.summary>small,.related small{background:#ebf5f4;color:#309689;padding:7px 10px;border-radius:8px}.save{position:absolute;right:0;font-size:26px}.title{display:flex;gap:18px;align-items:center;margin:24px 0}.title>b{font-size:40px}.title h2{font-size:40px;margin:0 0 12px}.title p{margin:0}.meta{display:flex;gap:25px;align-items:center;color:#6c757d}.meta span{display:flex;align-items:center;gap:8px}.meta img{width:24px;height:24px}.meta button{margin-left:auto;width:280px}.layout{display:grid;grid-template-columns:1fr 306px;gap:50px;padding:55px 0 110px}.content{font-size:15px;line-height:1.65}.content h3{font-size:20px;margin-top:38px}.content ul{list-style:none;padding:0}.content li{margin:13px 0}.content li:before{content:'✓';color:#309689;margin-right:14px}.tags{display:flex;gap:12px}.tags span{background:#ebf5f4;color:#309689;padding:8px 13px;border-radius:8px}.share{margin:35px 0 65px}.related-title{font-size:40px}.related{display:grid;gap:24px}.related>div{position:relative;padding:30px;border-radius:18px;box-shadow:0 3px 10px #30968918}.related>div>span{position:absolute;right:30px}.related h3{font-size:22px;margin:20px 0 4px}.related p{margin:0}.related footer{display:flex;justify-content:space-between;align-items:center;margin-top:22px}.related em{font-style:normal;color:#6c757d}aside>.apply{width:100%;margin-bottom:25px}.overview,aside form{background:#ebf5f4;border-radius:20px;padding:28px 20px;margin-bottom:28px}.overview h3,aside form h3{margin-top:0}.overview dl{margin:0}.overview dt{font-weight:650;margin-top:18px}.overview dt::first-letter{color:#309689}.overview dd{color:#6c757d;margin:5px 0 0 28px}.map{width:100%;height:266px;object-fit:cover;border:1px solid #b7c3cd;border-radius:12px;margin-top:25px}aside form{display:flex;flex-direction:column;gap:16px}aside label{height:42px;background:#fff;border-radius:10px;padding:0 12px;display:flex;align-items:center;gap:10px}aside label img{width:20px;height:20px}aside input,aside textarea{border:0;outline:0;width:100%;font:inherit}.message{height:160px!important;align-items:flex-start!important;padding-top:12px!important}.message textarea{height:130px;resize:none}.site-footer{background:#000;color:#fff;padding:90px 0 50px}.foot{display:grid;grid-template-columns:1.4fr .65fr .75fr 1fr;gap:60px}.foot p{color:#fffb}.foot>div:not(:first-child),.foot form{display:flex;flex-direction:column;gap:12px}.foot input{height:48px;background:transparent;border:1px solid #777;border-radius:10px;padding:0 15px}.copy{margin-top:70px;color:#888;display:flex;justify-content:space-between}
@media(max-width:850px){.nav nav{display:none}.layout{grid-template-columns:1fr}.meta{flex-wrap:wrap}.meta button{margin-left:0}.foot{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.shell{width:calc(100% - 32px)}.hero h1{font-size:45px}.title h2{font-size:30px}.meta{flex-direction:column;align-items:flex-start}.meta button{width:100%}.related footer{align-items:flex-start;gap:15px}.related em{line-height:2}.foot{grid-template-columns:1fr}.copy{flex-direction:column;gap:18px}}
.save{background:transparent!important;color:#6c757d;padding:0}.save.saved{color:#309689}.apply-form{background:#fff!important;border:1px solid #dcefed}.apply-form select{width:100%;border:0}.apply:disabled,.meta button:disabled{opacity:.65}
</style>
